import { promises as fs } from 'node:fs';for(const p of ['scripts/build.mjs','assets/atlas.css'])await fs.access(p).catch(()=>{throw new Error(`Eksik: ${p}`)});let b=await fs.readFile('scripts/build.mjs','utf8');if(!b.includes('V25.4 Compact Compass navigation')){b+='\n'+await fs.readFile('v25-4-build-patch.txt','utf8');await fs.writeFile('scripts/build.mjs',b)}let c=await fs.readFile('assets/atlas.css','utf8');if(!c.includes('V25.4 Compact Compass entry system')){c+='\n'+await fs.readFile('v25-4-css-patch.txt','utf8');await fs.writeFile('assets/atlas.css',c)}console.log('V25.4 kuruldu: Pusula menüde özel bir keşif çipine, yayınlarda kompakt sinyal şeridine dönüştürüldü.');
